#include <print>
#include <string>

int main() {
    std::string name = "fukase";
    int count = 0;

    for (auto c : name) {
        if (c == 'a' || c == 'e' || c == 'i') count++;
    }

    std::println("元音出现了 {} 次", count);

    std::string word = "hello";
    for (auto ch : word) {
        if (ch == 'l') {
            std::println("找到了");
        }
    }

    return 0;
}

